create or replace view public.location_publishability_audit as
select id, name, state, location_type, address, city, is_searchable, data_status, quality_status, source_quality_status, import_confidence, public_visibility_tier, duplicate_status, is_hidden, is_low_level, has_photos, photo_status, main_image, image_url, images, latitude, longitude,
  case when is_searchable = true and (state not in ('NY','NJ','CT') or quality_status is distinct from 'publish_ready' or coalesce(is_hidden,false)=true or coalesce(is_low_level,false)=true or public_visibility_tier in ('hidden','low_level','internal','pending_review','rejected') or source_quality_status in ('low_level_review','imported_unverified') or coalesce(import_confidence,'')='low' or coalesce(has_photos,false)=false or main_image is null or main_image='' or address is null or address='' or city is null or city='' or latitude is null or longitude is null or coalesce(duplicate_status,'unknown')='duplicate' or coalesce(status,'approved') in ('closed','archived','rejected')) then true else false end as has_searchability_bug,
  case when coalesce(is_searchable,false)=false and state in ('NY','NJ','CT') and coalesce(status,'approved')='approved' and location_type in ('restaurant','activity') and data_status='clean' and coalesce(public_visibility_tier,'standard')='standard' and coalesce(is_hidden,false)=false and coalesce(is_low_level,false)=false and coalesce(has_photos,false)=true and coalesce(main_image,image_url,'')<>'' and coalesce(address,'')<>'' and coalesce(city,'')<>'' and latitude is not null and longitude is not null and coalesce(duplicate_status,'unknown')<>'duplicate' and coalesce(source_quality_status,'') not in ('low_level_review','imported_unverified') and coalesce(import_confidence,'')<>'low' then true else false end as ready_to_approve
from public.locations;
